={{
  (() => {
    // Tenta pegar o estado; se der erro no parse ou não existir, assume 'inicio'
    let estado = 'inicio';
    try {
      const sessao = $json.dados_sessao?.parseJson();
      estado = sessao?.estado_anterior || 'inicio';
    } catch (e) {
      estado = 'inicio';
    }

    // Mapeamento de mensagens por estado
if($('Webhook').item.json.body.data.messageType != "textMessage"){ 
return "Opa, não consigo indentificar mensagens essa mensagem, somente texto"
}

    if (estado === 'cliente_novo') {
      return 'Ops! 😕 Não entendi. Por favor, responda apenas *1* para SIM ou *2* para NÃO para sabermos se você já é nosso cliente.';
    }

    if (estado === 'autorizado') {
      return 'Para prosseguir com a validação, preciso que você responda *1* para SIM ou *2* para NÃO.';
    }

    if (estado === 'AGUARDANDO_CPF') {
      return 'Desculpe, o CPF ou CNPJ informado parece inválido. Por favor, envie apenas os *números* do seu cadastro.';
    }

    if (estado === 'AGUARDANDO_CONFIRMAR') {
      return 'Para sua segurança, informe apenas os *4 primeiros dígitos* do CPF do responsável pela empresa.';
    }

    // Mensagem padrão caso caia em um estado desconhecido ou no menu inicial
    return 'Poxa, não consegui entender essa opção. 🤔\n\nPor favor, escolha uma das opções do menu ou digite *Sair* para reiniciar o atendimento.';
  })()
}}

