const msg = ($json.output && $json.output.length <= 2) ? $json.output : ($json.conversation || "").toLowerCase().trim();

const estado = $json.estado_anterior || 'Menu_Principal';
const nome = $json.pushName;

// --- 1. DEFINIÇÃO DOS MENUS ---

const menuPrincipal = {
        'apresentacao': `Olá, ${nome}! Tudo bem? O que gostaria de fazer?\n\n1️⃣ - Minhas faturas e Boletos\n2️⃣ - Boletos Vencidos\n3️⃣ - Atualizar meus dados\n\nPor favor, digite apenas o número.`,

    '1': { prox: 'Faturas', rota: 'ir_faturas' },
    '2': { prox: 'Boletos_vencidos', rota: 'ir_vencidos' },
    '3': { prox: 'Atualiza_Dados', rota: 'ir_dados' }
};

const menuFaturas = {
    'apresentacao': `📄 *Bifinance - Faturas*\n\n1️⃣ - Ver faturas abertas\n2️⃣ - Histórico de pagamentos\n0️⃣ - Voltar`,
    '1': { 
      txt: "🔍 Buscando faturas abertas...", 
      prox: 'Faturas', 
      rota: 'gerar_boleto' 
    },
    '0': { 
      prox: 'Menu_Principal', 
      rota: 'voltar' 
    }
};

const menuVencidos = {
    'apresentacao': `⚠️ *Bifinance - Boletos Vencidos*\n\n1️⃣ - Por data\n2️⃣ - Último boleto\n3️⃣ - Lista completa\n0️⃣ - Voltar`,

    '1': { 
      txt: "📅 Digite a data desejada:", 
      prox: 'Aguardando_Data', 
      rota: 'coletar_data' 
    },
    '0': { prox: 'Menu_Principal', rota: 'voltar' }
};


const gerarBoleto = {
  'apresentacao':'📄 boleto*\n\n1️⃣ - gerar PDF\n2️⃣ - gerar QRcode\n0️⃣ - Voltar',
  '1':{ 
        txt:"função em produção",
        prox:"Gerar_boleto", 
        rota:'executar_pdf_boleto'
  },
  '2':{
    txt:"função em produção", 
    prox:"Gerar_boleto", 
    rota:'executar_qrcode_boleto'
  },

  '0': {prox:'Faturas'}
}

// --- 2. MAPEAMENTO DE ESTADOS ---

const mapaMenus = {
    'Menu_Principal': menuPrincipal,
    'Faturas': menuFaturas,
    'Boletos_vencidos': menuVencidos,
    'Gerar_boleto':gerarBoleto
};



// --- 3. LÓGICA DE DECISÃO ---

let menuAtual = mapaMenus[estado] || menuPrincipal;
let selecao = menuAtual[msg];

// Se a seleção for válida
if (selecao) {
    let proximoEstado = selecao.prox;
    let textoEnvio = selecao.txt;

    // SE O USUÁRIO QUER VOLTAR OU SE A OPÇÃO NÃO TEM TEXTO PRÓPRIO:
    if (!textoEnvio) {
        textoEnvio = mapaMenus[proximoEstado].apresentacao;
    }

    return {
        ...$json,
        mensagem_texto: textoEnvio,
        proximo_estado: proximoEstado,
        rota_destino: selecao.rota
    };

} else {
    // FALLBACK: Se digitar errado, apenas repete o menu atual (apresentação)
    return {
        ...$json,
        mensagem_texto: menuAtual['apresentacao'],
        proximo_estado: estado,
        rota_destino: 'fallback'
    };
}
